const t={id:"exam-m1",moduleId:"m1-powerbi",title:"Power BI & Data Visualization Exam",description:"A 22-question exam covering the Power BI workflow, Power Query, data modeling, DAX, and report design — aligned to the Microsoft PL-300 skill areas.",passingScore:70,questions:[{id:"m1-e1",type:"mcq",prompt:"What is the correct high-level Power BI workflow?",points:1,options:["Visualize → Model → Transform → Get Data","Get Data → Transform → Model → Visualize → Share","Model → Get Data → Share → Visualize","Transform → Share → Model → Get Data"],correctIndex:1,explanation:"You acquire data, shape it, model it, then visualize and share."},{id:"m1-e2",type:"truefalse",prompt:"Power Query steps re-apply automatically on every data refresh.",points:1,correctBool:!0,explanation:"Applied Steps form a repeatable recipe that re-runs on refresh."},{id:"m1-e3",type:"mcq",prompt:"A date column imported as text breaks time-based visuals. The fix is to…",points:1,options:["Delete the column","Change its data type to Date","Sort the column","Hide the column"],correctIndex:1,explanation:"Correct data types are required for a proper time axis."},{id:"m1-e4",type:"mcq",prompt:"Which is a FACT table in a sales model?",points:1,options:["Customer","Date","SalesTransactions","Product"],correctIndex:2,explanation:"Facts store measurable events; the others are dimensions (context)."},{id:"m1-e5",type:"mcq",prompt:"The recommended data model shape for Power BI is…",points:1,options:["One big flat table","Star schema","Snowflake with many-to-many everywhere","No relationships"],correctIndex:1,explanation:"Star schema (facts + dimensions) is the recommended default."},{id:"m1-e6",type:"mcq",prompt:"Typical cardinality between a dimension and a fact table is…",points:1,options:["one-to-one","many-to-many","one-to-many","none"],correctIndex:2,explanation:"One dimension row relates to many fact rows."},{id:"m1-e7",type:"truefalse",prompt:"A measure is stored row-by-row in the model like a calculated column.",points:1,correctBool:!1,explanation:"Measures are computed on the fly per visual; they are not stored per row."},{id:"m1-e8",type:"mcq",prompt:"Which is best implemented as a MEASURE?",points:1,options:["A row-level tax category label","Total Sales across the current filter","A concatenated full-name column","A per-row age bucket"],correctIndex:1,explanation:"Aggregations that respond to filters are measures."},{id:"m1-e9",type:"mcq",prompt:"Which DAX function modifies the filter context of a calculation?",points:1,options:["SUM","CALCULATE","FORMAT","RELATED"],correctIndex:1,explanation:"CALCULATE evaluates an expression under modified filters."},{id:"m1-e10",type:"mcq",prompt:"Which DAX is a valid measure for total revenue?",points:1,options:["= COUNT(Amount)","= SUM('Sales'[Amount])","= 'Sales'[Amount]","= AVERAGEX(Amount)"],correctIndex:1,explanation:"SUM('Sales'[Amount]) aggregates the Amount column."},{id:"m1-e11",type:"mcq",prompt:"To show a value as a % of the total safely (avoiding divide-by-zero), use…",points:1,options:["/","DIVIDE","QUOTIENT","PERCENT"],correctIndex:1,explanation:"DIVIDE handles division by zero gracefully."},{id:"m1-e12",type:"mcq",prompt:"Best visual for a trend over 12 months?",points:1,options:["Pie chart","Line chart","3D column","Card"],correctIndex:1,explanation:"Line charts are standard for trends over time."},{id:"m1-e13",type:"mcq",prompt:"Best visual for a single KPI vs. a target?",points:1,options:["Scatter plot","KPI card / gauge","Treemap","Table"],correctIndex:1,explanation:"A KPI card or gauge communicates one number against a target."},{id:"m1-e14",type:"truefalse",prompt:'A large number like "$2M" with no target or comparison is good dashboard design.',points:1,correctBool:!1,explanation:"Numbers need context (vs. target/prior period) to support a decision."},{id:"m1-e15",type:"mcq",prompt:"Which lets report users filter a page themselves?",points:1,options:["Bookmarks only","Slicers","Themes","Tooltips"],correctIndex:1,explanation:"Slicers provide interactive self-service filtering."},{id:"m1-e16",type:"mcq",prompt:"Drill-through in Power BI is used to…",points:1,options:["Change the theme","Navigate to a detail page for a selected item","Refresh data","Publish the report"],correctIndex:1,explanation:"Drill-through opens a focused detail page for the selected context."},{id:"m1-e17",type:"truefalse",prompt:"Removing unused columns in Power Query can make the model smaller and faster.",points:1,correctBool:!0,explanation:"Fewer columns reduce model size and improve performance."},{id:"m1-e18",type:"mcq",prompt:"A dedicated Date dimension table is important mainly because it enables…",points:1,options:["Nicer colors","Time-intelligence calculations (YTD, etc.)","Faster typing","Row-level security"],correctIndex:1,explanation:"Time intelligence (TOTALYTD, SAMEPERIODLASTYEAR) needs a proper Date table."},{id:"m1-e19",type:"short",prompt:"In one sentence, why do BAs prefer Power Query steps over manually editing spreadsheet cells?",points:1,keywords:["repeat","refresh","automat","reproduc","auditable"],sampleAnswer:"Because the steps are repeatable and auditable — they re-apply automatically on every refresh.",explanation:"Reproducibility/auditability is the key benefit."},{id:"m1-e20",type:"short",prompt:"Name the two categories every table in a star schema falls into.",points:1,keywords:["fact","dimension"],sampleAnswer:"Fact tables and dimension tables.",explanation:"Facts = events/measures; dimensions = descriptive context."},{id:"m1-e21",type:"short",prompt:"A stakeholder asks for “a dashboard to see how the business is doing.” State one clarifying question you would ask first.",points:1,keywords:["question","decision","kpi","metric","goal","target","who","what"],sampleAnswer:"What decisions will you make with it, and which specific metrics/KPIs matter most?",explanation:"Clarify the decisions and KPIs before designing visuals."},{id:"m1-e22",type:"short",prompt:"Complete the BA principle: every chart on a dashboard should trace back to a stakeholder ____.",points:1,keywords:["question","need","decision","requirement"],sampleAnswer:"question (or decision/need).",explanation:"If a chart answers no question, it should not be there."}]},o={id:"exam-m2",moduleId:"m2-foundations",title:"BA Foundations & Core Concepts Exam",description:"A 22-question exam on what business analysis is, the BA role vs PM vs PO, the BACCM six core concepts, the requirements classification schema, requirements vs designs, and good-requirement characteristics — framed on IIBA BABOK v3.",passingScore:70,questions:[{id:"m2-e1",type:"mcq",prompt:"Per BABOK v3, business analysis is best defined as…",points:1,options:["Writing the technical code that implements a system","Enabling change in an enterprise by defining needs and recommending solutions that deliver value to stakeholders","Managing the project schedule, budget, and risks","Testing software to find defects before release"],correctIndex:1,explanation:"The BABOK definition centres on enabling change by defining needs and recommending value-delivering solutions."},{id:"m2-e2",type:"mcq",prompt:"Which role is primarily responsible for defining and documenting requirements?",points:1,options:["Project Manager","Business Analyst","Product Owner","QA Tester"],correctIndex:1,explanation:'The BA owns requirements and analysis — the "what and why". The PM owns delivery; the PO owns backlog priority.'},{id:"m2-e3",type:"mcq",prompt:"Deciding which features are built first, ordered by value, is chiefly the job of the…",points:1,options:["Business Analyst","Project Manager","Product Owner","Developer"],correctIndex:2,explanation:"Prioritising the backlog by value is the Product Owner's core responsibility."},{id:"m2-e4",type:"mcq",prompt:"Which chain reflects the correct BA reasoning order?",points:1,options:["Solution → Requirement → Need","Requirement → Solution → Need","Need → Requirement → Solution","Solution → Need → Requirement"],correctIndex:2,explanation:"You start from the need, express it as requirements, then deliver a solution — never solution-first."},{id:"m2-e5",type:"mcq",prompt:"Which of these is NOT one of the six BACCM core concepts?",points:1,options:["Change","Need","Schedule","Stakeholder"],correctIndex:2,explanation:"The six are Change, Need, Solution, Stakeholder, Value, and Context. Schedule is not one of them."},{id:"m2-e6",type:"mcq",prompt:'In BACCM, "Value" is best described as…',points:1,options:["The total budget of the project","The worth, importance, or usefulness of something to a stakeholder within a context","The number of requirements delivered","The technical quality of the code"],correctIndex:1,explanation:"Value is relative — always to a stakeholder and within a context."},{id:"m2-e7",type:"mcq",prompt:'In BACCM, "Context" refers to…',points:1,options:["The list of open defects","The circumstances that influence, are influenced by, and provide understanding of the change","The product backlog","The functional requirements only"],correctIndex:1,explanation:"Context is the surrounding circumstances (regulations, systems, calendar, people) that shape the change."},{id:"m2-e8",type:"mcq",prompt:'How should "Reduce late customer payments by 20% this year" be classified?',points:1,options:["Business requirement","Functional requirement","Non-functional requirement","Transition requirement"],correctIndex:0,explanation:"It states a high-level enterprise goal/outcome — a business requirement."},{id:"m2-e9",type:"mcq",prompt:'"The overdue-invoice list must load in under 2 seconds" is which type of requirement?',points:1,options:["Functional","Non-functional","Business","Stakeholder"],correctIndex:1,explanation:"It describes a quality attribute (performance) — a non-functional requirement."},{id:"m2-e10",type:"mcq",prompt:'"Migrate three years of historical invoices into the new system before go-live" is a…',points:1,options:["Business requirement","Functional requirement","Transition requirement","Non-functional requirement"],correctIndex:2,explanation:"It is a temporary capability needed only to move from the old state to the new — a transition requirement."},{id:"m2-e11",type:"mcq",prompt:"Which statement is a DESIGN rather than a requirement?",points:1,options:["A manager must be able to approve an invoice before payment","Users must be able to retrieve an invoice quickly",'A green "Approve" button sits at the top-right of the invoice screen with a confirmation dialog',"Overdue invoices must be visible to the accounts team"],correctIndex:2,explanation:'The button, its colour, and its placement describe a specific "how" — that is a design, not a need-focused requirement.'},{id:"m2-e12",type:"mcq",prompt:"Which is the best-written (good) requirement?",points:1,options:["The system should be fast and user-friendly","The report should look nice","The overdue list shall load within 2 seconds for up to 1,000 invoices","Make the app modern"],correctIndex:2,explanation:"It is unambiguous and testable with a measurable threshold; the others are vague wishes."},{id:"m2-e13",type:"truefalse",prompt:"A requirement describes what must be true (need-focused), while a design describes a specific way to achieve it (solution-focused).",points:1,correctBool:!0,explanation:'BABOK separates requirements (the "what") from designs (a "how"), even though the boundary is relative.'},{id:"m2-e14",type:"truefalse",prompt:"Transition requirements are permanent capabilities that remain in use long after go-live.",points:1,correctBool:!1,explanation:"Transition requirements are temporary — they enable the move from old to new (e.g., data migration, parallel run) and then retire."},{id:"m2-e15",type:"truefalse",prompt:"The Project Manager, not the Business Analyst, is primarily responsible for eliciting and documenting requirements.",points:1,correctBool:!1,explanation:"Requirements and analysis are the BA's responsibility; the PM owns scope, schedule, budget, and risk."},{id:"m2-e16",type:"truefalse",prompt:"In BACCM, the six core concepts are interdependent — you cannot fully understand one without the others.",points:1,correctBool:!0,explanation:"The concepts form a web: a solution needs a need, value needs a stakeholder, and all sit within a context."},{id:"m2-e17",type:"short",prompt:"Name the six core concepts of the BACCM.",points:1,keywords:["change","need","solution","stakeholder","value","context"],sampleAnswer:"Change, Need, Solution, Stakeholder, Value, and Context.",explanation:"These six always-present, interrelated concepts make up the Business Analysis Core Concept Model."},{id:"m2-e18",type:"short",prompt:"In one sentence, what is the difference between a functional and a non-functional requirement?",points:1,keywords:["what","does","behaviour","behavior","quality","how well","performance","feature"],sampleAnswer:"A functional requirement says what the system does (a behaviour/feature); a non-functional requirement says how well it does it (a quality such as performance, security, or usability).",explanation:"Functional = behaviour; non-functional = quality attribute."},{id:"m2-e19",type:"short",prompt:"In one sentence, how does the Business Analyst role differ from the Project Manager role?",points:1,keywords:["what","why","requirement","need","schedule","deliver","scope","right thing"],sampleAnswer:"The BA focuses on what is needed and why (defining needs and requirements — the right thing), while the PM focuses on delivering it on time and budget (scope, schedule, risk — building it right).",explanation:'BA = the "what/why"; PM = the "when/how" of delivery.'},{id:"m2-e20",type:"short",prompt:'A stakeholder asks you to "add an Export to Excel button." Why should a BA ask "why" before building it?',points:1,keywords:["need","problem","real","underlying","solution","right","outcome","better"],sampleAnswer:'Because the button is a guessed solution — asking "why" uncovers the underlying need (e.g., an automated monthly report), which may be met by a better solution than the requested button.',explanation:"The problem-first mindset traces a requested solution back to the real need."},{id:"m2-e21",type:"short",prompt:"List three characteristics of a good requirement.",points:1,keywords:["atomic","complete","consistent","unambiguous","testable","verifiable","feasible","prioritis","prioritiz"],sampleAnswer:"Any three of: atomic, complete, consistent, unambiguous, testable/verifiable, feasible, prioritised.",explanation:"Good requirements are unambiguous and testable, among the other BABOK/ISO 29148 qualities."},{id:"m2-e22",type:"short",prompt:"In one sentence, what is the difference between a requirement and a design?",points:1,keywords:["what","how","need","solution","must","specific"],sampleAnswer:"A requirement states what must be true (need-focused, independent of solution), while a design states a specific how to satisfy it (solution-focused).",explanation:'Requirement = the "what"; design = a specific "how".'}]},n={id:"exam-m3",moduleId:"m3-planning",title:"BA Planning & Monitoring Exam",description:"A 23-question exam on BABOK Knowledge Area 1: planning the BA approach (predictive vs adaptive), stakeholder engagement (Power/Interest, RACI), governance and change control, information management, and BA performance.",passingScore:70,questions:[{id:"m3-e1",type:"mcq",prompt:"Which BA Planning & Monitoring task decides HOW the analysis work will be performed?",points:1,options:["Plan the Business Analysis Approach","Elicit Requirements","Design the Solution","Validate Requirements"],correctIndex:0,explanation:"Plan the Business Analysis Approach defines the activities, deliverables, timing, and formality up front."},{id:"m3-e2",type:"mcq",prompt:"A predictive (plan-driven) approach is the better fit when…",points:1,options:["Requirements are highly uncertain and change often","Requirements are stable and the cost/risk of change is high","The team wants to demo working software every two weeks","Nobody knows what the solution should do yet"],correctIndex:1,explanation:"Predictive suits stable, well-understood requirements where up-front baselining and formal change control reduce risk."},{id:"m3-e3",type:"truefalse",prompt:"In an adaptive (Agile) approach, all requirements are fully defined and baselined before any build begins.",points:1,correctBool:!1,explanation:"Adaptive requirements emerge and are elaborated just-in-time each iteration, not baselined up front."},{id:"m3-e4",type:"mcq",prompt:"Which is characteristic of an ADAPTIVE approach?",points:1,options:["One large release at the end","A heavy up-front SRS signed off before coding","Frequent small increments with change welcomed each iteration","Change requests are actively discouraged"],correctIndex:2,explanation:"Adaptive delivery favours frequent increments and treats change as expected and valuable."},{id:"m3-e5",type:"mcq",prompt:"On an ERP programme you baseline the regulated ledger requirements but iterate on operational reporting. This is best described as…",points:1,options:["A purely predictive approach","A purely adaptive approach","A hybrid approach","No approach at all"],correctIndex:2,explanation:"A hybrid mixes predictive for stable/regulated parts with adaptive for uncertain parts."},{id:"m3-e6",type:"truefalse",prompt:"Higher complexity, risk, and compliance stakes generally push the BA approach toward more formality and documentation.",points:1,correctBool:!0,explanation:"The level of formality is dialled up as complexity, risk, and audit/compliance needs increase."},{id:"m3-e7",type:"mcq",prompt:"The Power/Interest grid analyzes each stakeholder along which two dimensions?",points:1,options:["Cost and schedule","Power (influence) and interest","Age and seniority","Skill and availability"],correctIndex:1,explanation:"The grid plots influence (power) against interest to choose an engagement strategy."},{id:"m3-e8",type:"mcq",prompt:"A stakeholder with HIGH power and HIGH interest should be…",points:1,options:["Monitored with minimal effort","Managed closely — engaged fully and collaboratively","Ignored until the end","Only informed after decisions are made"],correctIndex:1,explanation:"High-power, high-interest stakeholders are the key players — manage them closely."},{id:"m3-e9",type:"mcq",prompt:"A stakeholder with HIGH power but LOW interest is best handled by…",points:1,options:["Managing them closely with daily workshops","Keeping them satisfied without overloading them","Ignoring them entirely","Treating them as low priority to monitor"],correctIndex:1,explanation:"Keep high-power/low-interest stakeholders satisfied and never surprise them, but do not overload them."},{id:"m3-e10",type:"mcq",prompt:"A stakeholder with LOW power but HIGH interest should typically be…",points:1,options:["Kept informed — they are often advocates and helpers","Given final sign-off authority","Only monitored","Excluded from all communication"],correctIndex:0,explanation:"Low-power/high-interest stakeholders are kept informed; they frequently become advocates and hands-on helpers."},{id:"m3-e11",type:"truefalse",prompt:"Low-power, low-interest stakeholders should receive maximum effort and be managed closely.",points:1,correctBool:!1,explanation:'They are the "monitor" quadrant — minimal effort, watching for changes in their power or interest.'},{id:"m3-e12",type:"mcq",prompt:"In a RACI matrix, which role must appear exactly once per row?",points:1,options:["Responsible","Accountable","Consulted","Informed"],correctIndex:1,explanation:"Exactly one Accountable owns each outcome/sign-off; zero or two causes stalls or clashes."},{id:"m3-e13",type:"mcq",prompt:"In RACI, the person who actually does the work is the…",points:1,options:["Accountable","Consulted","Responsible","Informed"],correctIndex:2,explanation:"Responsible performs the work; Accountable owns the outcome and sign-off."},{id:"m3-e14",type:"mcq",prompt:'What distinguishes "Consulted" from "Informed" in RACI?',points:1,options:["Consulted is two-way input before the work; Informed is one-way notification after","They are identical","Informed gives input; Consulted only receives updates","Consulted signs off; Informed does the work"],correctIndex:0,explanation:"Consulted is a two-way conversation before doing the work; Informed is one-way, after the fact."},{id:"m3-e15",type:"truefalse",prompt:"Having two people marked Accountable on the same RACI row is a healthy, recommended design.",points:1,correctBool:!1,explanation:"Two Accountables split ownership and stall decisions; each row needs exactly one Accountable."},{id:"m3-e16",type:"mcq",prompt:"Governance of BA work primarily defines…",points:1,options:["Which colours to use in reports","Who makes decisions and how requirements are approved","The programming language for the build","The office seating plan"],correctIndex:1,explanation:"Governance sets decision-making roles, approval steps, and prioritization authority."},{id:"m3-e17",type:"mcq",prompt:"What is the correct order of a requirements change-control loop?",points:1,options:["Decide → raise → trace → assess","Raise → assess impact → decide → update baseline and trace","Update baseline → raise → assess → decide","Trace → decide → raise → assess"],correctIndex:1,explanation:"A change is raised, impact-assessed, decided by the right authority, then the baseline is updated and traced."},{id:"m3-e18",type:"truefalse",prompt:"Requirements traceability helps you answer why a requirement exists and what a proposed change would affect.",points:1,correctBool:!0,explanation:"Traceability links requirements to their source and to each other, supporting impact analysis and audit."},{id:"m3-e19",type:"mcq",prompt:"Which of these is NOT part of managing BA information?",points:1,options:["Deciding where requirements are stored","Deciding who can access and change them","Versioning and retention rules","Choosing the font used in the report"],correctIndex:3,explanation:"Managing BA information covers storage, access, versioning, and retention — not cosmetic formatting."},{id:"m3-e20",type:"truefalse",prompt:"Storing the only copy of your requirements in scattered personal email threads is good information management.",points:1,correctBool:!1,explanation:"Requirements should live in a shared, versioned, access-controlled repository — not private email."},{id:"m3-e21",type:"truefalse",prompt:"You cannot demonstrate that BA performance is improving unless you define and measure some metric.",points:1,correctBool:!0,explanation:"Improvement must be measured — pick honest metrics, run retrospectives, and check whether they move."},{id:"m3-e22",type:"short",prompt:"Name the two axes of the stakeholder Power/Interest grid.",points:1,keywords:["power","interest","influence"],sampleAnswer:"Power (influence) and interest.",explanation:"The grid plots power/influence against interest to choose an engagement strategy per quadrant."},{id:"m3-e23",type:"short",prompt:"Give one metric a business analyst could track to show that requirements work is improving.",points:1,keywords:["rework","change","changes","satisfaction","defect","exception","cycle","time","gap"],sampleAnswer:"The number of post-baseline change requests (or rework/defects caused by missed requirements) per release — it should trend down as elicitation and validation improve.",explanation:"Good BA metrics capture rework, post-baseline changes, cycle time, or stakeholder satisfaction and are tracked over time."}]},i={id:"exam-m4",moduleId:"m4-elicitation",title:"Elicitation & Collaboration Exam",description:"A 22-question exam covering elicitation techniques and when to use each, preparing/conducting/confirming elicitation, communicating BA information, and stakeholder collaboration and conflict — aligned to BABOK Knowledge Area 2.",passingScore:70,questions:[{id:"m4-e1",type:"mcq",prompt:'What best describes "elicitation" in business analysis?',points:1,options:["Passively collecting a ready-made requirements list","Actively drawing information out of stakeholders and sources","Writing the final requirements document","Testing the delivered software"],correctIndex:1,explanation:"Requirements rarely sit ready to gather; the BA actively draws them out."},{id:"m4-e2",type:"mcq",prompt:"A stakeholder performs a task expertly but cannot explain the steps (tacit knowledge). Which technique fits best?",points:1,options:["Survey","Document analysis","Observation / job-shadowing","Brainstorming"],correctIndex:2,explanation:"Observation captures hands-on, tacit knowledge the person can't articulate."},{id:"m4-e3",type:"mcq",prompt:"You need input from 50 branch staff on a well-understood set of questions, cheaply. Best technique?",points:1,options:["Interviews","Survey / questionnaire","Prototyping","One-on-one observation"],correctIndex:1,explanation:"Surveys reach many people at low cost for well-understood questions."},{id:"m4-e4",type:"mcq",prompt:"The best technique to get many stakeholders aligned quickly and build shared understanding is a…",points:1,options:["Survey","Workshop","Document review","Solo interview"],correctIndex:1,explanation:"Workshops bring stakeholders together to align and build shared understanding."},{id:"m4-e5",type:"mcq",prompt:'Requirements are fuzzy and stakeholders only "know it when they see it." Which technique helps most?',points:1,options:["Prototyping","Document analysis","Survey","Interview"],correctIndex:0,explanation:"A prototype makes the fuzzy concrete so stakeholders can react and refine."},{id:"m4-e6",type:"mcq",prompt:"Existing SOPs, reports, and system specs already contain the answers. Which technique should you start with?",points:1,options:["Brainstorming","Document analysis","Observation","Prototyping"],correctIndex:1,explanation:"Document analysis mines information that already exists in written form."},{id:"m4-e7",type:"truefalse",prompt:"A single elicitation session should usually rely on exactly one technique.",points:1,correctBool:!1,explanation:"Real projects combine techniques (e.g., document analysis, then interviews, then a workshop)."},{id:"m4-e8",type:"mcq",prompt:"Which activity belongs to PREPARING for elicitation?",points:1,options:["Reading captured notes back to stakeholders","Defining scope, stakeholders, technique and logistics","Coding the solution","Signing off on final requirements"],correctIndex:1,explanation:"Preparation sets scope, people, technique, materials and logistics before the session."},{id:"m4-e9",type:"truefalse",prompt:"During elicitation, a BA should generally talk more than the stakeholder to keep things moving.",points:1,correctBool:!1,explanation:"Listen more than you talk; open questions and silence draw out detail."},{id:"m4-e10",type:"mcq",prompt:"A good conducting technique is to start with open questions and then…",points:1,options:["End the session immediately","Narrow to specific, detailed questions","Avoid taking notes","Only ask yes/no questions"],correctIndex:1,explanation:"Open first for context, then close in on specifics — capturing accurately throughout."},{id:"m4-e11",type:"mcq",prompt:'The MAIN purpose of "confirm elicitation results" is to…',points:1,options:["Design the database","Check captured information for accuracy and completeness","Estimate project cost","Assign developers"],correctIndex:1,explanation:"Confirming checks that what you captured is accurate and has no gaps/contradictions."},{id:"m4-e12",type:"truefalse",prompt:"Confirming elicitation results is exactly the same task as formally validating requirements.",points:1,correctBool:!1,explanation:"Confirming results is a lightweight elicitation check; Requirements Validation is a separate, more rigorous task."},{id:"m4-e13",type:"mcq",prompt:"A common way to confirm elicitation results is to…",points:1,options:["Deploy to production","Read the captured process/rules back to the stakeholder","Delete the notes and re-interview from scratch","Ask developers to guess"],correctIndex:1,explanation:"A read-back / walkthrough lets stakeholders catch errors and fill gaps."},{id:"m4-e14",type:"mcq",prompt:'The BABOK task "Communicate Business Analysis Information" is mainly about…',points:1,options:["Writing code","Delivering the right information to the right stakeholders in the right form","Approving budgets","Running the servers"],correctIndex:1,explanation:"It ensures stakeholders receive information they can understand and act on."},{id:"m4-e15",type:"truefalse",prompt:"The same requirement should be communicated at the same level of detail to every audience.",points:1,correctBool:!1,explanation:"Tailor format and detail: high detail for developers, outcome-level for sponsors."},{id:"m4-e16",type:"mcq",prompt:"Which communication is best suited to an executive sponsor?",points:1,options:["Full technical spec with data rules","A one-page summary of goals, outcomes and cost/benefit","Raw interview notes","Detailed acceptance criteria"],correctIndex:1,explanation:"Sponsors need concise, outcome-focused information to make decisions."},{id:"m4-e17",type:"mcq",prompt:"Developers and QA typically need requirements communicated as…",points:1,options:["A verbal summary only","Precise, testable detail with acceptance criteria","A one-line benefit statement","A mood board"],correctIndex:1,explanation:"Build/test work needs precise, testable specifics, not high-level summaries."},{id:"m4-e18",type:"mcq",prompt:'The purpose of "Manage Stakeholder Collaboration" is to…',points:1,options:["Eliminate the need for stakeholders","Build and sustain productive working relationships and engagement","Automate all approvals","Replace elicitation with surveys"],correctIndex:1,explanation:"It keeps stakeholders engaged and working with the BA throughout the effort."},{id:"m4-e19",type:"mcq",prompt:"When two stakeholders conflict, the most constructive first move is to…",points:1,options:["Pick the more senior person's demand","Surface the underlying interests behind each position","End the project","Ignore the quieter stakeholder"],correctIndex:1,explanation:"Positions may clash while underlying interests overlap; surfacing interests opens solutions."},{id:"m4-e20",type:"truefalse",prompt:"A group agreement reached verbally should be written down with its decision, rationale, and who agreed.",points:1,correctBool:!0,explanation:"Recording the decision, rationale and sign-off prevents it being re-litigated later."},{id:"m4-e21",type:"short",prompt:"Name one elicitation technique that is best for capturing tacit, hands-on knowledge a stakeholder cannot explain.",points:1,keywords:["observ","shadow","job-shadow","watch"],sampleAnswer:"Observation / job-shadowing.",explanation:"Observation captures the tacit steps people do automatically and forget to describe."},{id:"m4-e22",type:"short",prompt:"In one sentence, why must a BA confirm elicitation results before building on them?",points:1,keywords:["accura","complete","gap","error","misunderst","contradict","correct"],sampleAnswer:"Because fast-captured notes contain errors and gaps, so you confirm accuracy and completeness before anything depends on them.",explanation:"Confirming catches misunderstandings, gaps and contradictions early."}]},a={id:"exam-m5",moduleId:"m5-rlcm",title:"Requirements Life Cycle Management Exam",description:"A 22-question exam covering traceability and the RTM, maintaining and reusing requirements, prioritization (MoSCoW and its bases), change assessment, and requirement approval — aligned to BABOK v3 Knowledge Area 3.",passingScore:70,questions:[{id:"m5-e1",type:"mcq",prompt:"Requirements traceability lets you follow a requirement in which directions?",points:1,options:["Only forward to tests","Only backward to the business need","Both backward to its source and forward to designs and tests","Neither; requirements are standalone"],correctIndex:2,explanation:"Traceability works backward to the originating need and forward to designs, code, and tests."},{id:"m5-e2",type:"mcq",prompt:"What is a Requirements Traceability Matrix (RTM)?",points:1,options:["A list of stakeholders","A grid linking requirements to their sources, designs, and tests","A project budget","A test automation tool"],correctIndex:1,explanation:"An RTM is a grid that records the links between requirements and related items so coverage is visible."},{id:"m5-e3",type:"mcq",prompt:"In the traceability chain, which order flows from intent to proof of delivery?",points:1,options:["Test → Design → Requirement → Goal","Goal → Requirement → Design → Test","Design → Goal → Test → Requirement","Requirement → Test → Goal → Design"],correctIndex:1,explanation:"Business goal justifies the requirement, which is realized in design and proven by a test."},{id:"m5-e4",type:"mcq",prompt:"A test case that proves a requirement is met represents which traceability relationship?",points:1,options:["Derive","Depends","Satisfy","Validate"],correctIndex:3,explanation:"A test or check *validates* that a requirement has been satisfied."},{id:"m5-e5",type:"mcq",prompt:"A design component that fulfills a requirement represents which relationship?",points:1,options:["Satisfy","Validate","Depends","Derive"],correctIndex:0,explanation:"A solution component *satisfies* a requirement."},{id:"m5-e6",type:"mcq",prompt:'"Send dunning email" cannot be done until "Detect overdue status" is met. This is which relationship?',points:1,options:["Derive","Depends","Satisfy","Validate"],correctIndex:1,explanation:"A necessity/effort dependency between requirements is a *depends* relationship."},{id:"m5-e7",type:"truefalse",prompt:"Traceability supports impact analysis by showing everything a changed requirement touches.",points:1,correctBool:!0,explanation:"Following the links reveals the designs, tests, and other requirements affected by a change."},{id:"m5-e8",type:"truefalse",prompt:"Once approved, requirements never need to be updated or maintained.",points:1,correctBool:!1,explanation:"The BA maintains requirements so they stay accurate as the solution and context change."},{id:"m5-e9",type:"mcq",prompt:"Why does a BA reuse well-written requirements across projects?",points:1,options:["To increase document length","Because they are durable organizational assets that save rework","To avoid approval","Because reuse is required by law"],correctIndex:1,explanation:"Long-lived requirements stored in a shared repository can be reused, saving effort and improving consistency."},{id:"m5-e10",type:"mcq",prompt:'In MoSCoW, what does "Must" mean?',points:1,options:["Nice to have if time allows","Non-negotiable for this release","Explicitly out of scope","A future maybe"],correctIndex:1,explanation:"A Must is essential; without it the release fails or is unacceptable."},{id:"m5-e11",type:"mcq",prompt:"Which MoSCoW category is the first to be dropped when a release slips?",points:1,options:["Must","Should","Could","Won't"],correctIndex:2,explanation:"Could items are desirable but low priority, so they are cut first."},{id:"m5-e12",type:"mcq",prompt:`In MoSCoW, "Won't (this time)" means the requirement is…`,points:1,options:["Rejected forever","Being built first","Explicitly agreed out of scope for now, possibly later","The highest priority"],correctIndex:2,explanation:`"Won't this time" parks an item for now while acknowledging it may return.`},{id:"m5-e13",type:"truefalse",prompt:'A healthy backlog where every item is labelled "Must" shows strong prioritization.',points:1,correctBool:!1,explanation:"If everything is a Must, nothing is prioritized — the ability to trade off is lost."},{id:"m5-e14",type:"mcq",prompt:"Which of these is NOT one of the common bases for prioritizing requirements?",points:1,options:["Business value","Risk","Dependencies","Alphabetical order of the requirement text"],correctIndex:3,explanation:"Prioritization weighs value, risk, cost/effort, and dependencies — not alphabetical order."},{id:"m5-e15",type:"mcq",prompt:"A low-value requirement is prioritized highly because many other requirements need it first. Which basis explains this?",points:1,options:["Business value","Dependencies","Cost","Aesthetics"],correctIndex:1,explanation:"A requirement that unblocks many others earns priority through dependency."},{id:"m5-e16",type:"mcq",prompt:"Using a value-vs-effort heuristic, which items should typically be done first?",points:1,options:["High value, low effort (quick wins)","Low value, high effort","Low value, low effort","High value, high effort"],correctIndex:0,explanation:"Quick wins — high value for low effort — are the natural first choices."},{id:"m5-e17",type:"mcq",prompt:"When a change request arrives, what should the BA do FIRST before recommending a decision?",points:1,options:["Immediately build it","Reject it to protect scope","Assess its impact, cost, and risk","Ask the developers to estimate the whole project again"],correctIndex:2,explanation:"A change is evaluated for impact, cost, benefit, and risk before accept/reject/defer."},{id:"m5-e18",type:"truefalse",prompt:"The RTM is a key tool for assessing the impact of a proposed requirement change.",points:1,correctBool:!0,explanation:"Tracing the links reveals every requirement, design, and test a change would affect."},{id:"m5-e19",type:"mcq",prompt:"What is the purpose of requirement approval / sign-off?",points:1,options:["To start elicitation","To gain authorized agreement and baseline the requirements","To write test cases","To choose a database"],correctIndex:1,explanation:"Approval is authorized agreement that establishes a committed baseline to build against."},{id:"m5-e20",type:"truefalse",prompt:"In a RACI, more than one person should be marked Accountable for a requirements sign-off.",points:1,correctBool:!1,explanation:"Exactly one role should be Accountable — the single sign-off authority; others may be Consulted or Informed."},{id:"m5-e21",type:"short",prompt:"In one sentence, what is requirements traceability?",points:1,keywords:["back","forward","source","origin","link","trace","design","test","need"],sampleAnswer:"The ability to follow a requirement backward to its source/business need and forward to the designs and tests that deliver and prove it.",explanation:"Traceability follows a requirement in both directions across its life."},{id:"m5-e22",type:"short",prompt:"Name two things a BA should record when logging an approval decision.",points:1,keywords:["approver","who","date","decision","condition","requirement","sign"],sampleAnswer:"The decision (approved/rejected/conditions), the approver, and the date.",explanation:"An auditable approval log captures what was decided, by whom, when, and under which conditions."}]},s={id:"exam-m6",moduleId:"m6-strategy",title:"Strategy Analysis Exam",description:"A 22-question exam covering the four tasks of BABOK Strategy Analysis: analyze the current state, define the future state, assess risks, and define the change strategy.",passingScore:70,questions:[{id:"m6-e1",type:"mcq",prompt:"What are the four tasks of Strategy Analysis, in order?",points:1,options:["Define change strategy → assess risks → future state → current state","Analyze current state → define future state → assess risks → define change strategy","Assess risks → analyze current state → define change strategy → future state","Future state → current state → change strategy → risks"],correctIndex:1,explanation:"You establish where you are, define where you want to be, weigh the risks, then choose how to get there."},{id:"m6-e2",type:"mcq",prompt:'A stakeholder says "we need a new dashboard." As a BA, what should you treat this statement as?',points:1,options:["The business need","A proposed solution to be validated against the real need","The future state","A risk"],correctIndex:1,explanation:"A requested tool is a solution; the BA must uncover the underlying business need before committing to it."},{id:"m6-e3",type:"truefalse",prompt:"A symptom and a root cause are the same thing.",points:1,correctBool:!1,explanation:"A symptom is what people feel; the root cause is why it happens. Fixing only the symptom lets the problem return."},{id:"m6-e4",type:"mcq",prompt:"The 5 Whys technique is used primarily to…",points:1,options:["Estimate project cost","Drill from a symptom down to an actionable root cause","Rank stakeholders","Design a database"],correctIndex:1,explanation:'Repeatedly asking "why" moves you from the visible symptom to the underlying cause you can act on.'},{id:"m6-e5",type:"mcq",prompt:"A fishbone (Ishikawa) diagram organizes possible causes by…",points:1,options:["Cost","Category (e.g., People, Process, System, Data)","Alphabetical order","Stakeholder seniority"],correctIndex:1,explanation:"The fishbone groups candidate causes into categories that all point at a single effect."},{id:"m6-e6",type:"truefalse",prompt:"A fishbone diagram is also known as a cause-and-effect or Ishikawa diagram.",points:1,correctBool:!0,explanation:"All three names refer to the same tool for mapping causes to an effect."},{id:"m6-e7",type:"mcq",prompt:"In SWOT, Strengths and Weaknesses are…",points:1,options:["External factors","Internal factors the organization controls","Risks","Future-state goals"],correctIndex:1,explanation:"Strengths and Weaknesses are internal; Opportunities and Threats are external."},{id:"m6-e8",type:"mcq",prompt:"A new statutory audit deadline that pressures the finance team is best placed in which SWOT quadrant?",points:1,options:["Strength","Weakness","Opportunity","Threat"],correctIndex:3,explanation:"It is external and harmful, which makes it a Threat."},{id:"m6-e9",type:"truefalse",prompt:"In SWOT, Opportunities are internal factors.",points:1,correctBool:!1,explanation:"Opportunities are external (helpful) factors; internal helpful factors are Strengths."},{id:"m6-e10",type:"mcq",prompt:"The future state in Strategy Analysis primarily describes…",points:1,options:["The exact software product to purchase","The capabilities, processes, data, and technology needed to meet the business need","The project budget only","The list of current defects"],correctIndex:1,explanation:"The future state describes needed capabilities, not a pre-chosen product."},{id:"m6-e11",type:"mcq",prompt:'What does the "M" in a SMART objective stand for?',points:1,options:["Motivational","Measurable","Mandatory","Managed"],correctIndex:1,explanation:"SMART = Specific, Measurable, Achievable, Relevant, Time-bound."},{id:"m6-e12",type:"truefalse",prompt:'"Make month-end faster" is a well-formed SMART objective.',points:1,correctBool:!1,explanation:"It has no measurable target and no deadline, so it fails the M and T of SMART."},{id:"m6-e13",type:"mcq",prompt:"Which is the most SMART objective?",points:1,options:["Improve reconciliation soon","Reduce month-end reconciliation from 5 days to under 1 day by Q4, with no manual matching","Try to save some time","Make the finance team happier"],correctIndex:1,explanation:"It is specific, measurable, time-bound, and tied to the business need."},{id:"m6-e14",type:"mcq",prompt:"A gap analysis compares…",points:1,options:["Two competing vendors","The current state against the future state to identify the work that closes the distance","Revenue against expenses","One team against another"],correctIndex:1,explanation:"The gap is the difference between current and future state; the gaps define the scope of change."},{id:"m6-e15",type:"truefalse",prompt:"The gaps found in a gap analysis often become the scope of the change.",points:1,correctBool:!0,explanation:"Each gap is work that must be done to reach the future state, so together they scope the change."},{id:"m6-e16",type:"mcq",prompt:"Risk is commonly assessed as a combination of…",points:1,options:["Cost and colour","Likelihood and impact","Time and headcount","Strengths and weaknesses"],correctIndex:1,explanation:"Risk severity is judged by how likely it is and how much impact it would have."},{id:"m6-e17",type:"mcq",prompt:"Buying insurance or requiring a vendor SLA to cover a risk is which response type?",points:1,options:["Avoid","Mitigate","Transfer","Accept"],correctIndex:2,explanation:"Shifting the consequence of a risk to a third party is a transfer response."},{id:"m6-e18",type:"mcq",prompt:"A small, low-impact risk that you acknowledge and simply monitor is being…",points:1,options:["Avoided","Accepted","Transferred","Escalated"],correctIndex:1,explanation:"When a risk is minor, acknowledging and monitoring it is an accept response."},{id:"m6-e19",type:"mcq",prompt:"Transition states in a change strategy are…",points:1,options:["The final future state only","Stable intermediate stages the organization passes through on the way to the future state","A list of risks","The current state frozen in time"],correctIndex:1,explanation:"Transition states are intermediate, stable stages that deliver value and reduce risk en route to the future state."},{id:"m6-e20",type:"truefalse",prompt:"A phased change strategy generally carries less risk than a big-bang cutover on a critical system.",points:1,correctBool:!0,explanation:"Phasing through transition states allows early wins, easier rollback, and lower risk than an all-at-once switch."},{id:"m6-e21",type:"short",prompt:"A change costs 50,000,000₫ and saves 5,000,000₫ per month. In one line, give its payback period.",points:1,keywords:["10","ten","month"],sampleAnswer:"Payback = 50,000,000 ÷ 5,000,000 = 10 months.",explanation:"Payback period = total cost ÷ monthly saving = 10 months."},{id:"m6-e22",type:"short",prompt:"Name any two components a lightweight business case should contain.",points:1,keywords:["cost","benefit","roi","payback","recommendation","need","risk"],sampleAnswer:"Costs and benefits (plus ROI/payback and a clear recommendation).",explanation:"A business case weighs costs against benefits, expresses ROI/payback, and ends with a recommendation."}]},r={id:"exam-m7",moduleId:"m7-radd",title:"Requirements Analysis & Design Definition Exam",description:"A 22-question exam covering user stories and INVEST, Gherkin acceptance criteria, use cases, BPMN modelling, ERDs and cardinality, verify vs validate, requirements architecture, and evaluating design options — aligned to BABOK Knowledge Area 5.",passingScore:70,questions:[{id:"m7-e1",type:"mcq",prompt:"Which is the correct user story format?",points:1,options:["As a <role>, I want <goal>, so that <benefit>","Given <state>, When <action>, Then <result>","The system shall <requirement>","Actor → Use Case → Flow"],correctIndex:0,explanation:"A user story states the role, the goal, and the benefit/value."},{id:"m7-e2",type:"mcq",prompt:'What does the "I" in INVEST stand for?',points:1,options:["Important","Independent","Iterative","Integrated"],correctIndex:1,explanation:"INVEST = Independent, Negotiable, Valuable, Estimable, Small, Testable."},{id:"m7-e3",type:"truefalse",prompt:"A good user story should be Testable, meaning you can prove when it is done.",points:1,correctBool:!0,explanation:'The "T" in INVEST is Testable — acceptance criteria make "done" provable.'},{id:"m7-e4",type:"mcq",prompt:"Which keywords structure a Gherkin acceptance-criteria scenario?",points:1,options:["Input / Process / Output","Given / When / Then","As a / I want / So that","Actor / Trigger / Outcome"],correctIndex:1,explanation:"Gherkin scenarios use Given (context), When (action), Then (expected result)."},{id:"m7-e5",type:"mcq",prompt:"What is the correct decomposition order, largest to smallest?",points:1,options:["Story → Feature → Epic","Feature → Epic → Story","Epic → Feature → Story","Epic → Story → Feature"],correctIndex:2,explanation:"An epic is decomposed into features, which are decomposed into stories."},{id:"m7-e6",type:"truefalse",prompt:"A use case describes an actor achieving a goal through a main flow plus alternate/exception flows.",points:1,correctBool:!0,explanation:"Use cases document the actor, the main flow, and alternate/exception flows."},{id:"m7-e7",type:"mcq",prompt:"When is a use case usually preferred over a user story?",points:1,options:["When you want the smallest possible increment","When the interaction is procedural and branch-heavy","When you want to avoid documenting flows","When there is no actor involved"],correctIndex:1,explanation:"Use cases shine for procedural, multi-branch interactions; stories favour small negotiable increments."},{id:"m7-e8",type:"mcq",prompt:"In BPMN, a diamond shape represents a…",points:1,options:["Event","Activity","Gateway","Pool"],correctIndex:2,explanation:"A diamond is a gateway — a decision or branch/merge in the flow."},{id:"m7-e9",type:"mcq",prompt:"In BPMN, a rounded rectangle represents a…",points:1,options:["Start event","Activity/task","Sequence flow","Gateway"],correctIndex:1,explanation:"A rounded rectangle is an activity or task — a unit of work."},{id:"m7-e10",type:"mcq",prompt:"BPMN swimlanes (lanes within a pool) are primarily used to show…",points:1,options:["The order of steps","Which role/participant performs each activity","The data model","The project timeline"],correctIndex:1,explanation:"Lanes assign responsibility — who does each activity — and reveal hand-offs."},{id:"m7-e11",type:"truefalse",prompt:"An As-Is model shows the current process, while a To-Be model shows the improved future process.",points:1,correctBool:!0,explanation:"As-Is = current state; To-Be = future state after improvements."},{id:"m7-e12",type:"mcq",prompt:"Why model the As-Is process before designing the To-Be?",points:1,options:["To skip stakeholder input","To surface real delays, rework and hand-offs and build a baseline","Because To-Be models are optional","To increase the number of steps"],correctIndex:1,explanation:"The As-Is reveals actual pain points and provides a baseline to improve against."},{id:"m7-e13",type:"mcq",prompt:"In an ERD, what does a foreign key (FK) do?",points:1,options:["Uniquely identifies each row of its own entity","Stores a calculated total","References the primary key of another entity to link them","Encrypts the data"],correctIndex:2,explanation:"A foreign key holds another entity’s primary key, creating the relationship."},{id:"m7-e14",type:"mcq",prompt:"One Customer can have many Invoices. This relationship is…",points:1,options:["one-to-one (1:1)","one-to-many (1:M)","many-to-many (M:N)","none"],correctIndex:1,explanation:"One customer relates to many invoices — a classic one-to-many relationship."},{id:"m7-e15",type:"mcq",prompt:"A many-to-many (M:N) relationship in a relational model is usually resolved by adding a…",points:1,options:["Primary key only","Link/junction entity","Gateway","Swimlane"],correctIndex:1,explanation:"An associative/link entity turns an M:N into two 1:M relationships."},{id:"m7-e16",type:"truefalse",prompt:"A primary key uniquely identifies each row of an entity.",points:1,correctBool:!0,explanation:"That is exactly the role of a primary key."},{id:"m7-e17",type:"mcq",prompt:"Verifying a requirement answers which question?",points:1,options:["Are we building the right thing?","Are we building it right?","How much does it cost?","Who is the sponsor?"],correctIndex:1,explanation:"Verification checks the quality of the requirement — are we building it right (clear, complete, testable)."},{id:"m7-e18",type:"mcq",prompt:"Validating a requirement primarily confirms that it…",points:1,options:["Is grammatically correct","Delivers business value and traces to an objective","Uses the right font","Has a foreign key"],correctIndex:1,explanation:"Validation confirms the requirement is the right thing to build — it delivers value."},{id:"m7-e19",type:"truefalse",prompt:"A requirement can be well-written (verified) yet still fail validation because it is the wrong thing to build.",points:1,correctBool:!0,explanation:"Verify and validate are distinct; passing one does not guarantee the other."},{id:"m7-e20",type:"mcq",prompt:"Requirements architecture is best described as…",points:1,options:["A single user story","The structure showing how all requirements fit together and support the goals","A database backup","A project budget"],correctIndex:1,explanation:"It is the coherent structure — complete, consistent, traceable — of all requirements."},{id:"m7-e21",type:"mcq",prompt:"When evaluating design options and making a make-vs-buy decision, a BA should…",points:1,options:["Always build custom","Always buy off-the-shelf","Score options against weighted criteria and recommend with trade-offs stated","Pick the cheapest without analysis"],correctIndex:2,explanation:"Evaluate against explicit weighted criteria and recommend transparently, stating trade-offs."},{id:"m7-e22",type:"short",prompt:"In one sentence, explain the difference between verifying and validating a requirement.",points:1,keywords:["right","quality","value","need","correct","build"],sampleAnswer:"Verifying checks we are building the requirement right (clear, complete, testable), while validating checks we are building the right thing (it delivers business value).",explanation:"Verify = built right (quality); Validate = right thing (value/need)."}]},c={id:"exam-m8",moduleId:"m8-solution",title:"Solution Evaluation Exam",description:"A 23-question exam on BABOK Solution Evaluation: defining measures and KPIs (leading vs. lagging), collecting and analyzing performance data, comparing actual vs. expected value, distinguishing enterprise from solution limitations, and recommending value-increasing actions.",passingScore:70,questions:[{id:"m8-e1",type:"mcq",prompt:"The purpose of Solution Evaluation (BABOK Knowledge Area 6) is to…",points:1,options:["Elicit new requirements for a future project","Assess the performance and value a solution in use delivers, and recommend action","Write test cases before development starts","Design the user interface"],correctIndex:1,explanation:"Solution Evaluation measures and analyzes a delivered solution and recommends actions to increase its value."},{id:"m8-e2",type:"mcq",prompt:"A KPI differs from an ordinary metric because it…",points:1,options:["Is always financial","Directly indicates whether a key business objective is being met","Can only be measured once a year","Requires no target"],correctIndex:1,explanation:"A KPI is a key metric tied to a business objective; a generic metric may not indicate objective attainment."},{id:"m8-e3",type:"mcq",prompt:"Which of these is a LEADING indicator?",points:1,options:["Prior-quarter month-end close time","% of invoices auto-matched today","Total revenue recognized last year","Number of defects found after release"],correctIndex:1,explanation:"Auto-match rate today predicts whether the close will be on time — a predictive, leading measure."},{id:"m8-e4",type:"mcq",prompt:"Which of these is a LAGGING indicator?",points:1,options:["% of users trained this week","Predicted backlog for tomorrow","Actual days to close the books this month","The current auto-match rate"],correctIndex:2,explanation:"Days to close reports an outcome after it has happened — a confirmatory, lagging measure."},{id:"m8-e5",type:"truefalse",prompt:"Leading indicators are predictive and let you act before an outcome is final.",points:1,correctBool:!0,explanation:"Leading indicators give early warning so you can steer while there is still time."},{id:"m8-e6",type:"truefalse",prompt:"A good KPI can be defined without linking it to any business objective.",points:1,correctBool:!1,explanation:"Every good KPI traces back to a business objective; otherwise it measures nothing that matters."},{id:"m8-e7",type:"mcq",prompt:"The SMART criteria for a measure stand for…",points:1,options:["Simple, Modern, Agile, Ready, Tested","Specific, Measurable, Achievable, Relevant, Time-bound","Strategic, Managed, Automated, Reliable, Tracked","Standard, Metric, Actual, Rated, Targeted"],correctIndex:1,explanation:"SMART = Specific, Measurable, Achievable, Relevant, Time-bound."},{id:"m8-e8",type:"mcq",prompt:"Before go-live you should capture a ____ so you can prove improvement later.",points:1,options:["baseline","backlog","burndown","bug report"],correctIndex:0,explanation:"A baseline is the pre-solution number the post-go-live results are compared against."},{id:"m8-e9",type:"truefalse",prompt:"Without a pre-solution baseline you cannot credibly demonstrate improvement.",points:1,correctBool:!0,explanation:"With no baseline there is nothing to compare the new numbers to, so improvement cannot be proven."},{id:"m8-e10",type:"mcq",prompt:"Which is a valid source for a QUANTITATIVE performance KPI?",points:1,options:["A hallway conversation","System audit logs / ERP tables","A gut feeling","A vendor brochure"],correctIndex:1,explanation:"System-generated logs and ERP tables give objective, quantitative counts and durations."},{id:"m8-e11",type:"mcq",prompt:"Qualitative performance data (for example user interviews) is useful mainly because it…",points:1,options:["Replaces the need for metrics","Captures satisfaction and context that logs cannot","Is always more accurate than counts","Requires no analysis"],correctIndex:1,explanation:"Qualitative data surfaces user satisfaction and reasons that quantitative logs do not capture."},{id:"m8-e12",type:"mcq",prompt:"Analyzing performance (as opposed to merely measuring it) primarily means…",points:1,options:["Collecting even more data","Comparing actual results against expected/target value and explaining the variance","Formatting a report","Archiving the numbers"],correctIndex:1,explanation:"Analysis is the actual-vs-expected comparison and the interpretation of the gap."},{id:"m8-e13",type:"truefalse",prompt:"A single below-target month is always enough to declare the solution a failure.",points:1,correctBool:!1,explanation:"One month is noise; you look at the trend before drawing a conclusion."},{id:"m8-e14",type:"mcq",prompt:"Actual cycle time is 2.5 days against a 2.0-day target. The correct first BA step is to…",points:1,options:["Immediately replace the solution","Analyze whether the gap comes from the solution, the surrounding process, or the measure","Delete the KPI","Raise the target to 3 days"],correctIndex:1,explanation:"You diagnose the cause of the variance before recommending any action."},{id:"m8-e15",type:"mcq",prompt:"A software defect that slows a report is an example of a…",points:1,options:["Enterprise limitation","Solution limitation","Baseline","Leading indicator"],correctIndex:1,explanation:"A defect lives inside the solution, so it is a solution limitation."},{id:"m8-e16",type:"mcq",prompt:"Untrained staff and dirty upstream data are examples of…",points:1,options:["Solution limitations","Enterprise limitations","KPIs","Lagging indicators"],correctIndex:1,explanation:"These constraints live in the organization around the solution, so they are enterprise limitations."},{id:"m8-e17",type:"truefalse",prompt:"If reconciliation is slow only because users were never trained, buying a new module will fix it.",points:1,correctBool:!1,explanation:"That is an enterprise limitation; new software will not address a training gap."},{id:"m8-e18",type:"mcq",prompt:"The solution cannot meet the need and cannot be economically fixed. Which recommendation fits?",points:1,options:["Do nothing","Adjust","Replace the solution","Raise the target"],correctIndex:2,explanation:"When a solution cannot meet needs and cannot be economically adjusted, replacing it is the fit."},{id:"m8-e19",type:"mcq",prompt:"A legacy report is fully duplicated by the new dashboard and no longer needed. Recommend…",points:1,options:["Replace","Retire the solution","Increase investment","Adjust"],correctIndex:1,explanation:"The need is served elsewhere, so decommission (retire) the redundant solution."},{id:"m8-e20",type:"mcq",prompt:"A KPI is 1% off target and any change is costly and risky. The best recommendation is often…",points:1,options:["Do nothing","Replace","Retire","Rebuild from scratch"],correctIndex:0,explanation:"When the gap is trivial and change is costly, doing nothing preserves value."},{id:"m8-e21",type:"short",prompt:"Name the two categories BABOK uses to classify what limits a solution value.",points:1,keywords:["solution","enterprise"],sampleAnswer:"Solution limitations and enterprise limitations.",explanation:"Solution limitations live in the software; enterprise limitations live in the organization around it."},{id:"m8-e22",type:"short",prompt:"In one sentence, explain the difference between a leading and a lagging indicator.",points:1,keywords:["predict","before","after","future","past","outcome","early"],sampleAnswer:"A leading indicator predicts a future outcome so you can act early, while a lagging indicator confirms an outcome after it has already happened.",explanation:"Leading = predictive and early; lagging = confirmatory and after the fact."},{id:"m8-e23",type:"short",prompt:"List two of BABOK possible recommendations for increasing a solution delivered value.",points:1,keywords:["do nothing","adjust","replace","retire","invest","organiz"],sampleAnswer:"Any two of: do nothing, adjust (organizational change), replace the solution, retire the solution, or increase investment.",explanation:"The BABOK menu is: do nothing, adjust/organizational change, replace, retire, or increase investment."}]},p={id:"exam-m9",moduleId:"m9-agile-capstone",title:"Agile, Tools & Capstone Exam",description:"A 22-question exam covering Agile Scrum (roles, ceremonies, artifacts, backlog), SQL fundamentals (SELECT, JOIN, GROUP BY), the BRD and requirements package, and the IIBA certification/career path.",passingScore:70,questions:[{id:"m9-e1",type:"mcq",prompt:"Which Scrum role owns the Product Backlog and its priorities?",points:1,options:["Scrum Master","Product Owner","Development Team","Project Sponsor"],correctIndex:1,explanation:"The Product Owner owns and orders the Product Backlog — the role a BA most often overlaps with."},{id:"m9-e2",type:"mcq",prompt:"Which of these is a Scrum ARTIFACT (not a ceremony or role)?",points:1,options:["Sprint Planning","Sprint Backlog","Scrum Master","Daily Scrum"],correctIndex:1,explanation:"The artifacts are the Product Backlog, Sprint Backlog and Increment; the others are an event and a role."},{id:"m9-e3",type:"mcq",prompt:"The four Scrum ceremonies are Sprint Planning, Daily Scrum, Sprint Review and…",points:1,options:["Backlog Grooming","Sprint Retrospective","Steering Committee","Go-Live"],correctIndex:1,explanation:"The Sprint Retrospective closes the sprint by improving how the team works."},{id:"m9-e4",type:"mcq",prompt:'The working, "Done" output produced at the end of each sprint is called the…',points:1,options:["Release","Increment","Milestone","Epic"],correctIndex:1,explanation:"The Increment is the usable, Done result of a sprint."},{id:"m9-e5",type:"truefalse",prompt:'Backlog refinement is where a BA writes and slices user stories and adds acceptance criteria so items become "Ready".',points:1,correctBool:!0,explanation:"Refinement keeps the top of the backlog clear, valuable, estimable and small — the heart of the BA role in Scrum."},{id:"m9-e6",type:"mcq",prompt:"Which is the standard user-story format?",points:1,options:["Given / When / Then","As a <role>, I want <goal>, so that <benefit>","Shall / Should / May","Who / What / When"],correctIndex:1,explanation:"The As a / I want / so that form captures role, goal and value; Given/When/Then is for acceptance criteria."},{id:"m9-e7",type:"mcq",prompt:"In a Scrum team, which tool typically holds the backlog as issues on a board, and which holds the deeper requirements docs?",points:1,options:["Confluence for the board, Jira for docs","Jira for the board, Confluence for docs","Both in Jira only","Both in Confluence only"],correctIndex:1,explanation:"Jira manages the backlog/board (Epic → Story → Sub-task); Confluence is the wiki for BRDs, models and notes."},{id:"m9-e8",type:"truefalse",prompt:"The Daily Scrum is a 15-minute sync where the team shares progress and blockers.",points:1,correctBool:!0,explanation:"The Daily Scrum is a short daily sync; the BA often answers requirement questions and helps unblock the team."},{id:"m9-e9",type:"mcq",prompt:"Which SQL clause filters the rows returned by a query?",points:1,options:["SELECT","WHERE","ORDER BY","GROUP BY"],correctIndex:1,explanation:"WHERE filters rows; SELECT picks columns, ORDER BY sorts, GROUP BY aggregates."},{id:"m9-e10",type:"mcq",prompt:"Which clause combines rows from two tables and keeps only rows that match on both sides?",points:1,options:["UNION","INNER JOIN","GROUP BY","ORDER BY"],correctIndex:1,explanation:"An INNER JOIN stitches tables on a shared key and returns only matching rows."},{id:"m9-e11",type:"mcq",prompt:"To return the total amount per customer, which clause groups the rows so SUM can aggregate within each group?",points:1,options:["ORDER BY CustomerName","GROUP BY CustomerName","WHERE CustomerName","DISTINCT CustomerName"],correctIndex:1,explanation:"GROUP BY collapses rows into groups; every non-aggregated SELECT column must appear in GROUP BY."},{id:"m9-e12",type:"mcq",prompt:"Which set are all SQL aggregate functions?",points:1,options:["SUM, COUNT, AVG","JOIN, WHERE, ORDER","SELECT, FROM, WHERE","MERGE, SPLIT, TRIM"],correctIndex:0,explanation:"SUM, COUNT and AVG aggregate values across the rows in each group."},{id:"m9-e13",type:"truefalse",prompt:"ORDER BY Amount DESC sorts the result from the largest amount to the smallest.",points:1,correctBool:!0,explanation:"DESC sorts descending (largest first); ASC (the default) sorts ascending."},{id:"m9-e14",type:"truefalse",prompt:"In Excel, XLOOKUP can combine two sheets on a key, serving the same purpose as a JOIN in SQL.",points:1,correctBool:!0,explanation:"XLOOKUP (or VLOOKUP) matches a key across sheets to pull in related values, much like a join."},{id:"m9-e15",type:"mcq",prompt:"Which BRD section explicitly states what the project will NOT deliver, to prevent scope creep?",points:1,options:["Assumptions","Scope — Out","Success Metrics","Constraints"],correctIndex:1,explanation:"Scope — Out names what is excluded, protecting the project from creeping additions."},{id:"m9-e16",type:"mcq",prompt:"Which statement is a FUNCTIONAL requirement rather than a business requirement?",points:1,options:["Close the books faster each month","The system shall auto-match statement lines to ledger entries where date and amount are equal","Improve the finance team’s efficiency","Reduce reconciliation errors"],correctIndex:1,explanation:"A functional requirement is a specific, testable thing the system must do; the others are high-level business goals."},{id:"m9-e17",type:"mcq",prompt:'A fixed, non-negotiable limit such as "must ship before year-end" or "must run on the existing SQL Server" is a…',points:1,options:["Assumption","Constraint","Success metric","Functional requirement"],correctIndex:1,explanation:"A constraint is a hard limit; an assumption is something believed true but not yet verified."},{id:"m9-e18",type:"truefalse",prompt:'A good success metric attaches a concrete target to an objective, e.g. "reduce reconciliation time from 3 days to 0.5 day".',points:1,correctBool:!0,explanation:"Metrics with targets turn opinions into measurable acceptance criteria."},{id:"m9-e19",type:"mcq",prompt:"For a career-changer with no formal BA experience, which IIBA certification is the right starting point?",points:1,options:["CBAP","CCBA","ECBA","PMP"],correctIndex:2,explanation:"ECBA is the entry-level certificate with no experience requirement; CCBA and CBAP require thousands of logged BA hours."},{id:"m9-e20",type:"short",prompt:"Name the three Scrum artifacts.",points:1,keywords:["product backlog","sprint backlog","increment"],sampleAnswer:"The Product Backlog, the Sprint Backlog, and the Increment.",explanation:"These three artifacts represent the desired work, the committed work, and the delivered work."},{id:"m9-e21",type:"short",prompt:"In one sentence, what does the STAR method stand for and what is it used for?",points:1,keywords:["situation","task","action","result","interview","behav"],sampleAnswer:"Situation, Task, Action, Result — a structure for answering behavioural interview questions with a concrete, outcome-focused story.",explanation:"STAR keeps behavioural answers structured and centred on your specific action and its measurable result."},{id:"m9-e22",type:"short",prompt:"Write a one-line description of a SQL query that returns the total invoice amount per customer (mention the join and the grouping).",points:1,keywords:["join","sum","group by","customer","amount"],sampleAnswer:"INNER JOIN Invoices to Customers on CustomerID, then GROUP BY CustomerName with SUM(Amount) to total each customer.",explanation:"Joining the tables and grouping by customer lets SUM aggregate the amount per customer — a core BA query."}]},l=[t,o,n,i,a,s,r,c,p],d=new Map(l.map(e=>[e.moduleId,e]));function m(e){return d.get(e)}export{m as g};
